(function(l){"use strict";var e=function(){if(!Object.keys(resumeDataRecord).length)return;l("#resume_data_opportunity_type").val(resumeDataRecord.fulltime_or_internship);l("#resume_data_github_profile").val(resumeDataRecord.github_profile);l("#resume_data_linkedin_profile").val(resumeDataRecord.linkedin_profile);l("#resume_data_expected_salary").val(resumeDataRecord.expected_salary);l("#resume_data_will_relocate").prop("checked",resumeDataRecord.will_relocate);l("#resume_data_experience").val(resumeDataRecord.experience);l("#resume_data_join_from").val(resumeDataRecord.join_from.split(" ")[0]);l("#resume_data_contact_number").val(resumeDataRecord.contact_number);l("#resume_data_graduation_year").val(resumeDataRecord.graduation_year);l("#resume_data_can_contact").prop("checked",resumeDataRecord.can_contact);l("select").material_select()};l(document).ready(function(){l(".datepicker").pickadate({selectMonths:true,selectYears:10,format:"yyyy-mm-dd",min:new Date,closeOnSelect:true});l("#resume-data-form").submit(function(e){var a=2*1024*1024;var r=l("#resume_data_file");if(r.get(0).files.length){var t=r.get(0).files[0].size;if(t>a){l.web2py.flash("Please upload file smaller than 2 MB");return false}}if(l("#resume_data_opportunity_type").val()===null){l.web2py.flash("Please select Job/Internship");return false}if(l("#resume_data_join_from").val()===""){l.web2py.flash("Please enter when will you be able to join");return false}if(l("#resume_data_graduation_year").val()===""){l.web2py.flash("Please enter your graduation year");return false}});e()})})(jQuery);